<?php require_once '../config/app.php';require_once '../includes/security.php';start_secure_session();require_permission('users.export');$pdo=db();$rows=$pdo->query("SELECT u.user_uid,p.first_name,p.middle_name,p.last_name,u.mobile,u.email,p.date_of_birth,p.gender,p.category,p.domicile_state,u.account_status,u.created_at FROM users u LEFT JOIN user_profiles p ON p.user_id=u.id ORDER BY u.created_at DESC")->fetchAll();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=users-'.date('Y-m-d').'.csv');$out=fopen('php://output','w');fputcsv($out,['User ID','First Name','Middle Name','Last Name','Mobile','Email','DOB','Gender','Category','Domicile State','Status','Created']);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;